"""Inserts dash between two odd numbers.

    Examples:
        >>> assert insert_dash_between_odds_common(113345566) == "1-1-3-345-566"
    """
def insert_dash_between_odds_common(number: int) -> str {
    index: int = 0;
    result: str = str();
    while (index != len(str(number))) {
        result += str(number)[index];
        if not ((index + 1) >= len(str(number))) {
            if (
                (int(str(number)[index]) % 2) and (int(str(number)[(index + 1)]) % 2)
            ) {
                result += "-";
            }
        }
        index += 1;
    }
    return result;
}

"""
    Normalizes the score by centering it at 0.5 and scale it by 2 standard deviations. Values below 0 or above 1
    are clipped.
    :param score: The score to standardize.
    :param mean: The mean score for this subject.
    :param std: The standard deviation of scores for the subject.
    :return: The score centered at 0.5 and scaled by 2 standard deviations.
    """
def normalize_score(score: Any, mean: Any, std: Any) -> object {
    score -= mean;
    if (std != 0) {
        score /= std * 2;
    }
    score += 0.5;
    if (score < 0) {
        score = 0;
    } elif (score > 1) {
        score = 1;
    }
    return score;
}

"""
    Takes in a number of seconds and returns a string
    representing the seconds broken into hours, minutes and seconds.

    For example, format_seconds(3750.4) returns '1 h 2 min 30.40 s'.
    """
def format_seconds(seconds: Any) -> object {
    minutes = int((seconds // 60));
    hours = int((minutes // 60));
    remainder_sec = seconds % 60;
    remainder_min = minutes % 60;
    output_str = "";
    if (hours != 0) {
        output_str += f"{hours} h ";
    }
    if (minutes != 0) {
        output_str += f"{remainder_min} min ";
    }
    output_str += f"{remainder_sec:.2f} s";
    return output_str;
}

"""
	Validates that a discovery config is valid for a specific service class
	"""
def validate_config(config: Any, service_class: Any) -> object {
    header = config.setdefault('header', {});
    if (service_class != header.get('service_class')) {
        raise Exception(
            (
                "Cannot store config hash of type %s in service class %s: %s"
                % (header.get('service_class'), service_class, config)
            )
        );
    }
    return config;
}

"""

    Parameters
    ----------
    list_values : list
        List with different values

    Returns
    -------
    list_no_nones : list
        List with extract of list_values. No more None values included
    """
def erase_none_val_from_list(list_values: Any) -> object {
    list_no_nones = [];
    for val in list_values {
        if (val is not None) {
            list_no_nones.append(val);
        }
    }
    return list_no_nones;
}

